import { expect, test } from "@playwright/test";
import { sendFeedback } from "../src/lib/server/feedback";

const config = { RESEND_API_KEY: "test-key", FEEDBACK_FROM_EMAIL: "Exposed <feedback@example.com>" };
function submission(email = "visitor@example.com", message = "Please add more filters.") {
  const data = new FormData();
  data.set("email", email);
  data.set("message", message);
  return data;
}

test("invalid feedback never reaches the email provider", async () => {
  for (const data of [submission("invalid"), submission("visitor@example.com", "  "), submission("visitor@example.com", "x".repeat(10001))]) {
    const result = await sendFeedback(data, config, async () => { throw new Error("Provider must not be called"); });
    expect(result.kind).toBe("invalid");
  }
});

test("unconfigured feedback retains the visitor's input", async () => {
  expect(await sendFeedback(submission(), {})).toEqual({ kind: "unavailable", values: { email: "visitor@example.com", message: "Please add more filters." } });
});

test("accepted feedback uses a fixed recipient and visitor reply-to", async () => {
  let request: Request | undefined;
  const result = await sendFeedback(submission(), config, async (url, options) => {
    request = new Request(url, options);
    return Response.json({ id: "accepted-email" });
  });
  expect(result).toEqual({ kind: "success" });
  expect(request?.url).toBe("https://api.resend.com/emails");
  expect(request?.headers.get("Authorization")).toBe("Bearer test-key");
  expect(await request?.json()).toEqual({ from: config.FEEDBACK_FROM_EMAIL, to: ["james.richardson.2556@gmail.com"], reply_to: "visitor@example.com", subject: "Exposed product feedback", text: "Please add more filters." });
});

test("provider rejection and network failure retain feedback for retry", async () => {
  const providers: (typeof fetch)[] = [async () => new Response(null, { status: 429 }), async () => { throw new Error("Network unavailable"); }];
  for (const provider of providers) {
    expect(await sendFeedback(submission(), config, provider)).toEqual({ kind: "failed", values: { email: "visitor@example.com", message: "Please add more filters." } });
  }
});
